// src/components/LeadKanban.js

import React, { useState } from "react";
import { motion } from "framer-motion";
import { Trash2, Star, Tag, Building2, Info, Calendar } from "lucide-react"; // Thêm icon mới
import "../styles/leads.css";

const columns = [
  { key: "new", label: "Mới", color: "#38bdf8" },
  { key: "processing", label: "Đang xử lý", color: "#facc15" },
  { key: "converted", label: "Chuyển đổi", color: "#4ade80" },
  { key: "lost", label: "Mất", color: "#f87171" },
];

const LeadKanban = ({ leads = [], onUpdate, onDelete, onDrop, onEdit, onDragStart }) => {
  const [isDragging, setIsDragging] = useState(false);

  // Các hàm xử lý kéo thả không thay đổi
  const handleDragStart = (e, lead) => {
    setIsDragging(false);
    e.dataTransfer.setData("lead", JSON.stringify(lead));
    if (onDragStart) onDragStart(lead);
  };
  const handleDrag = () => setIsDragging(true);
  const handleDrop = (e, status) => {
    e.preventDefault();
    const lead = JSON.parse(e.dataTransfer.getData("lead"));
    if (onDrop) onDrop(status, lead);
  };
  const handleClick = (lead) => {
    if (!isDragging && onEdit) onEdit(lead);
  };

  return (
    <div className="kanban-container">
      {columns.map(col => (
        <div
          key={col.key}
          className="kanban-column"
          onDragOver={e => e.preventDefault()}
          onDrop={e => handleDrop(e, col.key)}
        >
          <div className="kanban-header" style={{ borderBottom: `3px solid ${col.color}` }}>
            <h3>{col.label}</h3>
            <span className="lead-count">{leads.filter(l => l.status === col.key).length}</span>
          </div>
          <div className="kanban-list">
            {leads.filter(l => l.status === col.key).map(lead => (
              <motion.div
                key={lead._id}
                className="kanban-card"
                draggable
                onDragStart={e => handleDragStart(e, lead)}
                onDrag={handleDrag}
                onClick={() => handleClick(lead)}
                whileHover={{ scale: 1.03, boxShadow: "0 4px 12px rgba(0,0,0,0.1)" }}
                whileTap={{ scale: 0.98 }}
              >
                {/* === PHẦN HEADER CỦA CARD === */}
                <div className="kanban-card-header">
                  <h4>{lead.name}</h4>
                  <button
                    className="delete-btn"
                    onClick={e => { e.stopPropagation(); onDelete(lead._id); }}
                  >
                    <Trash2 size={16} />
                  </button>
                </div>

                {/* === PHẦN THÔNG TIN CHI TIẾT (NÂNG CẤP) === */}
                <div className="kanban-card-body">
                  {/* Hiển thị Tên Công ty nếu có */}
                  {lead.company && (
                    <div className="kanban-card-detail-row">
                      <Building2 size={14} />
                      <span>{lead.company}</span>
                    </div>
                  )}

                  {/* Hiển thị Chủ đề nếu có */}
                  {lead.subject && (
                    <div className="kanban-card-detail-row">
                      <Info size={14} />
                      <span>{lead.subject}</span>
                    </div>
                  )}

                  {/* Hiển thị Ngày tạo */}
                  <div className="kanban-card-detail-row">
                    <Calendar size={14} />
                    <span>{new Date(lead.createdAt).toLocaleDateString('vi-VN')}</span>
                  </div>
                </div>

                {/* === PHẦN FOOTER CỦA CARD (SCORE & SOURCE) === */}
                <div className="kanban-card-meta">
                  <span className="meta-tag source-tag">
                    <Tag size={14} /> {lead.source || 'N/A'}
                  </span>
                  <span className="meta-tag score-tag">
                    <Star size={14} /> {lead.score || 0}
                  </span>
                </div>
              </motion.div>
            ))}
          </div>
        </div>
      ))}
    </div>
  );
};

export default LeadKanban;
